{
  "name": "opencode-memory-plugin",
  "version": "0.1.0",
  "description": "ZCode-style persistent project memory for OpenCode v2 — file-based memories, MEMORY.md index, and background extraction",
  "license": "MIT",
  "author": "liuhuimin",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Liuhmsir/opencode-memory-plugin.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "ai-agent"
  ],
  "type": "module",
  "exports": {
    ".": "./index.ts"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.18"
  },
  "devDependencies": {
    "typescript": "^5.9.2",
    "@types/node": "^24.0.0",
    "@opencode/client": "2.0.18"
  },
  "scripts": {
    "typecheck": "tsc -p tsconfig.json",
    "test": "bun test test/",
    "test:e2e": "RUN_E2E=1 bun test e2e/"
  }
}
